def auto(x,y,kleur,flip=False,s=1.0):
    f=' scale(-1 1) translate(-72 0)' if flip else ''
    return f'<g transform="translate({x} {y}) scale({s}){f}">'+use('s10-auto',0,0,72,40,kleur)+'</g>'
def pino_tas10(x,y,s=1.0,flip=False):
    f=' scale(-1 1) translate(-48 0)' if flip else ''
    return f'<g transform="translate({x} {y}) scale({s}){f}">'+use('pino-loop',0,0,48,72)+use('s9-stetho',0,0,48,72)+use('s10-tas',0,0,48,72)+'</g>'
def lantaarn_aan(x,y,s=1.0):
    return use('s10-gloed',x-28*s,y-26*s,80*s,80*s)+use('s9-lantaarn',x,y,24*s,80*s)
